@startuml

class Product {
  + Name : string
  + Description : string
  + NetPrice : double
  + Manufacturer : string
  + CountryOfManufacture : string
}

class VATRate {
  + Rate : float
  + Currency : string
  + ConversionToEuro : float
}

class Representative {
  + FirstName : string
  + LastName : string
  + Ssn : int
  + TelephoneNumber : string
  + EmailAddress : string
  + CountryRepresented : string
}

class Customer {
  + Name : string
  + Address : string
  + TelephoneNumber : string
  + EmailAddress : string
  + CountriesReselling : List<string>
}

class Order {
  + OrderId : int
  + Product : Product
  + Quantity : int
  + OrderDate : datetime
  + DesiredDeliveryDate : datetime
}

Representative "1" -- "*" Customer
Product "0..*" -- "1" VATRate
Order "1" -- "1" Representative
Order "1" -- "1" Product

@enduml

